32	typedef struct _memory_header memory_header;
33	struct _memory_header {
34	    size_t          magic1;
35	    size_t          size;
36	    size_t          alloc;
37	    memory_header   *prev;
38	    memory_header   *next;
39	    memory_header   *prev_free;
40	    memory_header   *next_free;
41	#if defined(MBEDTLS_MEMORY_BACKTRACE)
42	    char            **trace;
43	    size_t          trace_count;
44	#endif
45	    size_t          magic2;
46	};
47	
48	typedef struct {
49	    unsigned char   *buf;
50	    size_t          len;
51	    memory_header   *first;
52	    memory_header   *first_free;
53	    int             verify;
54	#if defined(MBEDTLS_MEMORY_DEBUG)
55	    size_t          alloc_count;
56	    size_t          free_count;
57	    size_t          total_used;
58	    size_t          maximum_used;
59	    size_t          header_count;
60	    size_t          maximum_header_count;
61	#endif
62	#if defined(MBEDTLS_THREADING_C)
63	    mbedtls_threading_mutex_t   mutex;
64	#endif
65	}
