113	static int verify_header(memory_header *hdr)
114	{
115	    if (hdr->magic1 != MAGIC1) {
116	#if defined(MBEDTLS_MEMORY_DEBUG)
117	        mbedtls_fprintf(stderr, "FATAL: MAGIC1 mismatch\n");
118	#endif
119	        return 1;
120	    }
121	
122	    if (hdr->magic2 != MAGIC2) {
123	#if defined(MBEDTLS_MEMORY_DEBUG)
124	        mbedtls_fprintf(stderr, "FATAL: MAGIC2 mismatch\n");
125	#endif
126	        return 1;
127	    }
128	
129	    if (hdr->alloc > 1) {
130	#if defined(MBEDTLS_MEMORY_DEBUG)
131	        mbedtls_fprintf(stderr, "FATAL: alloc has illegal value\n");
132	#endif
133	        return 1;
134	    }
135	
136	    if (hdr->prev != NULL && hdr->prev == hdr->next) {
137	#if defined(MBEDTLS_MEMORY_DEBUG)
138	        mbedtls_fprintf(stderr, "FATAL: prev == next\n");
139	#endif
140	        return 1;
141	    }
142	
143	    if (hdr->prev_free != NULL && hdr->prev_free == hdr->next_free) {
144	#if defined(MBEDTLS_MEMORY_DEBUG)
145	        mbedtls_fprintf(stderr, "FATAL: prev_free == next_free\n");
146	#endif
147	        return 1;
148	    }
149	
150	    return 0;
151	}
152	
153	static int verify_chain(void)
154	{
155	    memory_header *prv = heap.first, *cur;
156	
157	    if (prv == NULL || verify_header(prv) != 0) {
158	#if defined(MBEDTLS_MEMORY_DEBUG)
159	        mbedtls_fprintf(stderr, "FATAL: verification of first header "
160	                                "failed\n");
161	#endif
162	        return 1;
163	    }
164	
165	    if (heap.first->prev != NULL) {
166	#if defined(MBEDTLS_MEMORY_DEBUG)
167	        mbedtls_fprintf(stderr, "FATAL: verification failed: "
168	                                "first->prev != NULL\n");
169	#endif
170	        return 1;
171	    }
172	
173	    cur = heap.first->next;
174	
175	    while (cur != NULL) {
176	        if (verify_header(cur) != 0) {
177	#if defined(MBEDTLS_MEMORY_DEBUG)
178	            mbedtls_fprintf(stderr, "FATAL: verification of header "
179	                                    "failed\n");
180	#endif
181	            return 1;
182	        }
183	
184	        if (cur->prev != prv) {
185	#if defined(MBEDTLS_MEMORY_DEBUG)
186	            mbedtls_fprintf(stderr, "FATAL: verification failed: "
187	                                    "cur->prev != prv\n");
188	#endif
189	            return 1;
190	        }
191	
192	        prv = cur;
193	        cur = cur->next;
194	    }
195	
196	    return 0;
197	}
