199	static void *buffer_alloc_calloc(size_t n, size_t size)
200	{
201	    memory_header *new, *cur = heap.first_free;
202	    unsigned char *p;
203	    void *ret;
204	    size_t original_len, len;
205	#if defined(MBEDTLS_MEMORY_BACKTRACE)
206	    void *trace_buffer[MAX_BT];
207	    size_t trace_cnt;
208	#endif
209	
210	    if (heap.buf == NULL || heap.first == NULL) {
211	        return NULL;
212	    }
213	
214	    original_len = len = n * size;
215	
216	    if (n == 0 || size == 0 || len / n != size) {
217	        return NULL;
218	    } else if (len > (size_t) -MBEDTLS_MEMORY_ALIGN_MULTIPLE) {
219	        return NULL;
220	    }
221	
222	    if (len % MBEDTLS_MEMORY_ALIGN_MULTIPLE) {
223	        len -= len % MBEDTLS_MEMORY_ALIGN_MULTIPLE;
224	        len += MBEDTLS_MEMORY_ALIGN_MULTIPLE;
225	    }
226	
227	    // Find block that fits
228	    //
229	    while (cur != NULL) {
230	        if (cur->size >= len) {
231	            break;
232	        }
233	
234	        cur = cur->next_free;
235	    }
236	
237	    if (cur == NULL) {
238	        return NULL;
239	    }
240	
241	    if (cur->alloc != 0) {
242	#if defined(MBEDTLS_MEMORY_DEBUG)
243	        mbedtls_fprintf(stderr, "FATAL: block in free_list but allocated "
244	                                "data\n");
245	#endif
246	        mbedtls_exit(1);
247	    }
248	
249	#if defined(MBEDTLS_MEMORY_DEBUG)
250	    heap.alloc_count++;
251	#endif
252	
253	    // Found location, split block if > memory_header + 4 room left
254	    //
255	    if (cur->size - len < sizeof(memory_header) +
256	        MBEDTLS_MEMORY_ALIGN_MULTIPLE) {
257	        cur->alloc = 1;
258	
259	        // Remove from free_list
260	        //
261	        if (cur->prev_free != NULL) {
262	            cur->prev_free->next_free = cur->next_free;
263	        } else {
264	            heap.first_free = cur->next_free;
265	        }
266	
267	        if (cur->next_free != NULL) {
268	            cur->next_free->prev_free = cur->prev_free;
269	        }
270	
271	        cur->prev_free = NULL;
272	        cur->next_free = NULL;
273	
274	#if defined(MBEDTLS_MEMORY_DEBUG)
275	        heap.total_used += cur->size;
276	        if (heap.total_used > heap.maximum_used) {
277	            heap.maximum_used = heap.total_used;
278	        }
279	#endif
280	#if defined(MBEDTLS_MEMORY_BACKTRACE)
281	        trace_cnt = backtrace(trace_buffer, MAX_BT);
282	        cur->trace = backtrace_symbols(trace_buffer, trace_cnt);
283	        cur->trace_count = trace_cnt;
284	#endif
285	
286	        if ((heap.verify & MBEDTLS_MEMORY_VERIFY_ALLOC) && verify_chain() != 0) {
287	            mbedtls_exit(1);
288	        }
289	
290	        ret = (unsigned char *) cur + sizeof(memory_header);
291	        memset(ret, 0, original_len);
292	
293	        return ret;
294	    }
295	
296	    p = ((unsigned char *) cur) + sizeof(memory_header) + len;
297	    /* Double casting is required to prevent compilation warning on Clang-based
298	     * compilers when "-Wcast-align" is used. */
299	    new = (memory_header *) (void *) p;
300	
301	    new->size = cur->size - len - sizeof(memory_header);
302	    new->alloc = 0;
303	    new->prev = cur;
304	    new->next = cur->next;
305	#if defined(MBEDTLS_MEMORY_BACKTRACE)
306	    new->trace = NULL;
307	    new->trace_count = 0;
308	#endif
309	    new->magic1 = MAGIC1;
310	    new->magic2 = MAGIC2;
311	
312	    if (new->next != NULL) {
313	        new->next->prev = new;
314	    }
315	
316	    // Replace cur with new in free_list
317	    //
318	    new->prev_free = cur->prev_free;
319	    new->next_free = cur->next_free;
320	    if (new->prev_free != NULL) {
321	        new->prev_free->next_free = new;
322	    } else {
323	        heap.first_free = new;
324	    }
325	
326	    if (new->next_free != NULL) {
327	        new->next_free->prev_free = new;
328	    }
329	
330	    cur->alloc = 1;
331	    cur->size = len;
332	    cur->next = new;
333	    cur->prev_free = NULL;
334	    cur->next_free = NULL;
335	
336	#if defined(MBEDTLS_MEMORY_DEBUG)
337	    heap.header_count++;
338	    if (heap.header_count > heap.maximum_header_count) {
339	        heap.maximum_header_count = heap.header_count;
340	    }
341	    heap.total_used += cur->size;
342	    if (heap.total_used > heap.maximum_used) {
343	        heap.maximum_used = heap.total_used;
344	    }
345	#endif
346	#if defined(MBEDTLS_MEMORY_BACKTRACE)
347	    trace_cnt = backtrace(trace_buffer, MAX_BT);
348	    cur->trace = backtrace_symbols(trace_buffer, trace_cnt);
349	    cur->trace_count = trace_cnt;
350	#endif
351	
352	    if ((heap.verify & MBEDTLS_MEMORY_VERIFY_ALLOC) && verify_chain() != 0) {
353	        mbedtls_exit(1);
354	    }
355	
356	    ret = (unsigned char *) cur + sizeof(memory_header);
357	    memset(ret, 0, original_len);
358	
359	    return ret;
360	}
