362	static void buffer_alloc_free(void *ptr)
363	{
364	    memory_header *hdr, *old = NULL;
365	    unsigned char *p = (unsigned char *) ptr;
366	
367	    if (ptr == NULL || heap.buf == NULL || heap.first == NULL) {
368	        return;
369	    }
370	
371	    if (p < heap.buf || p >= heap.buf + heap.len) {
372	#if defined(MBEDTLS_MEMORY_DEBUG)
373	        mbedtls_fprintf(stderr, "FATAL: mbedtls_free() outside of managed "
374	                                "space\n");
375	#endif
376	        mbedtls_exit(1);
377	    }
378	
379	    p -= sizeof(memory_header);
380	    /* Double casting is required to prevent compilation warning on Clang-based
381	     * compilers when "-Wcast-align" is used. */
382	    hdr = (memory_header *) (void *) p;
383	
384	    if (verify_header(hdr) != 0) {
385	        mbedtls_exit(1);
386	    }
387	
388	    if (hdr->alloc != 1) {
389	#if defined(MBEDTLS_MEMORY_DEBUG)
390	        mbedtls_fprintf(stderr, "FATAL: mbedtls_free() on unallocated "
391	                                "data\n");
392	#endif
393	        mbedtls_exit(1);
394	    }
395	
396	    hdr->alloc = 0;
397	
398	#if defined(MBEDTLS_MEMORY_DEBUG)
399	    heap.free_count++;
400	    heap.total_used -= hdr->size;
401	#endif
402	
403	#if defined(MBEDTLS_MEMORY_BACKTRACE)
404	    free(hdr->trace);
405	    hdr->trace = NULL;
406	    hdr->trace_count = 0;
407	#endif
408	
409	    // Regroup with block before
410	    //
411	    if (hdr->prev != NULL && hdr->prev->alloc == 0) {
412	#if defined(MBEDTLS_MEMORY_DEBUG)
413	        heap.header_count--;
414	#endif
415	        hdr->prev->size += sizeof(memory_header) + hdr->size;
416	        hdr->prev->next = hdr->next;
417	        old = hdr;
418	        hdr = hdr->prev;
419	
420	        if (hdr->next != NULL) {
421	            hdr->next->prev = hdr;
422	        }
423	
424	        memset(old, 0, sizeof(memory_header));
425	    }
426	
427	    // Regroup with block after
428	    //
429	    if (hdr->next != NULL && hdr->next->alloc == 0) {
430	#if defined(MBEDTLS_MEMORY_DEBUG)
431	        heap.header_count--;
432	#endif
433	        hdr->size += sizeof(memory_header) + hdr->next->size;
434	        old = hdr->next;
435	        hdr->next = hdr->next->next;
436	
437	        if (hdr->prev_free != NULL || hdr->next_free != NULL) {
438	            if (hdr->prev_free != NULL) {
439	                hdr->prev_free->next_free = hdr->next_free;
440	            } else {
441	                heap.first_free = hdr->next_free;
442	            }
443	
444	            if (hdr->next_free != NULL) {
445	                hdr->next_free->prev_free = hdr->prev_free;
446	            }
447	        }
448	
449	        hdr->prev_free = old->prev_free;
450	        hdr->next_free = old->next_free;
451	
452	        if (hdr->prev_free != NULL) {
453	            hdr->prev_free->next_free = hdr;
454	        } else {
455	            heap.first_free = hdr;
456	        }
457	
458	        if (hdr->next_free != NULL) {
459	            hdr->next_free->prev_free = hdr;
460	        }
461	
462	        if (hdr->next != NULL) {
463	            hdr->next->prev = hdr;
464	        }
465	
466	        memset(old, 0, sizeof(memory_header));
467	    }
468	
469	    // Prepend to free_list if we have not merged
470	    // (Does not have to stay in same order as prev / next list)
471	    //
472	    if (old == NULL) {
473	        hdr->next_free = heap.first_free;
474	        if (heap.first_free != NULL) {
475	            heap.first_free->prev_free = hdr;
476	        }
477	        heap.first_free = hdr;
478	    }
479	
480	    if ((heap.verify & MBEDTLS_MEMORY_VERIFY_FREE) && verify_chain() != 0) {
481	        mbedtls_exit(1);
482	    }
483	}
