540	#if defined(MBEDTLS_THREADING_C)
541	static void *buffer_alloc_calloc_mutexed(size_t n, size_t size)
542	{
543	    void *buf;
544	    if (mbedtls_mutex_lock(&heap.mutex) != 0) {
545	        return NULL;
546	    }
547	    buf = buffer_alloc_calloc(n, size);
548	    if (mbedtls_mutex_unlock(&heap.mutex)) {
549	        return NULL;
550	    }
551	    return buf;
552	}
553	
554	static void buffer_alloc_free_mutexed(void *ptr)
555	{
556	    /* We have no good option here, but corrupting the heap seems
557	     * worse than losing memory. */
558	    if (mbedtls_mutex_lock(&heap.mutex)) {
559	        return;
560	    }
561	    buffer_alloc_free(ptr);
562	    (void) mbedtls_mutex_unlock(&heap.mutex);
563	}
564	#endif /* MBEDTLS_THREADING_C */
