566	void mbedtls_memory_buffer_alloc_init(unsigned char *buf, size_t len)
567	{
568	    memset(&heap, 0, sizeof(buffer_alloc_ctx));
569	
570	#if defined(MBEDTLS_THREADING_C)
571	    mbedtls_mutex_init(&heap.mutex);
572	    mbedtls_platform_set_calloc_free(buffer_alloc_calloc_mutexed,
573	                                     buffer_alloc_free_mutexed);
574	#else
575	    mbedtls_platform_set_calloc_free(buffer_alloc_calloc, buffer_alloc_free);
576	#endif
577	
578	    if (len < sizeof(memory_header) + MBEDTLS_MEMORY_ALIGN_MULTIPLE) {
579	        return;
580	    } else if ((size_t) buf % MBEDTLS_MEMORY_ALIGN_MULTIPLE) {
581	        /* Adjust len first since buf is used in the computation */
582	        len -= MBEDTLS_MEMORY_ALIGN_MULTIPLE
583	               - (size_t) buf % MBEDTLS_MEMORY_ALIGN_MULTIPLE;
584	        buf += MBEDTLS_MEMORY_ALIGN_MULTIPLE
585	               - (size_t) buf % MBEDTLS_MEMORY_ALIGN_MULTIPLE;
586	    }
587	
588	    memset(buf, 0, len);
589	
590	    heap.buf = buf;
591	    heap.len = len;
592	
593	    /* Double casting is required to prevent compilation warning on Clang-based
594	     * compilers when "-Wcast-align" is used. */
595	    heap.first = (memory_header *) (void *) buf;
596	    heap.first->size = len - sizeof(memory_header);
597	    heap.first->magic1 = MAGIC1;
598	    heap.first->magic2 = MAGIC2;
599	    heap.first_free = heap.first;
600	}
