602	void mbedtls_memory_buffer_alloc_free(void)
603	{
604	#if defined(MBEDTLS_THREADING_C)
605	    mbedtls_mutex_free(&heap.mutex);
606	#endif
607	    mbedtls_platform_zeroize(&heap, sizeof(buffer_alloc_ctx));
608	}
